```javascript
import * as THREE from 'three/webgpu';
import * as TSL from 'three/tsl';
import { gsap } from 'gsap';

const createNode = (config, ctx) => {
  const group = new THREE.Group();
  group.position.set(0, 0, 0);

  const cardsData = [
    { number: '01', title: 'In-House Calibre', body: 'Every movement is designed, machined, and finished under one roof.' },
    { number: '02', title: 'Five-Year Guarantee', body: 'Each piece is serviced free of charge for five years from delivery.' },
    { number: '03', title: 'Hand-Finished Dials', body: 'Guilloche cut on a 1912 rose engine, one dial at a time.' }
  ];

  const cardWidth = 1.5;
  const cardHeight = 1.9;
  const cardGap = 0.25;
  const rowTotal = 5.0;
  const startX = -(rowTotal / 2) + (cardWidth / 2);

  const cards = [];
  const timelines = [];

  cardsData.forEach((cardData, index) => {
    const cardGroup = new THREE.Group();
    cardGroup.position.set(startX + index * (cardWidth + cardGap), 0, 0);

    // Card background with gradient
    const cardGeo = new THREE.PlaneGeometry(cardWidth, cardHeight);
    const cardMaterial = new THREE.MeshStandardNodeMaterial({
      colorNode: TSL.mix(
        TSL.color(0x191921),
        TSL.color(0x121218),
        TSL.uv().y
      ),
      roughnessNode: TSL.float(0.6),
      metalnessNode: TSL.float(0.25),
      clearcoatNode: TSL.float(0.15)
    });

    const cardMesh = new THREE.Mesh(cardGeo, cardMaterial);
    cardMesh.castShadow = true;
    cardMesh.receiveShadow = true;
    cardGroup.add(cardMesh);

    // Icon seat disc (machined metal)
    const discGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.05, 32);
    const discMaterial = new THREE.MeshStandardNodeMaterial({
      colorNode: TSL.color(0x16161d),
      roughnessNode: TSL.float(0.55),
      metalnessNode: TSL.float(0.5),
      clearcoatNode: TSL.float(0.2)
    });

    const discMesh = new THREE.Mesh(discGeo, discMaterial);
    discMesh.position.y = cardHeight / 2 - 0.375 - 0.2;
    discMesh.position.z = 0.02;
    discMesh.castShadow = true;
    discMesh.receiveShadow = true;
    cardGroup.add(discMesh);

    // Icon glyph (number)
    const iconMesh = ctx.fontAtlas(cardData.number, {
      font: 'JetBrains Mono',
      size: 20,
      weight: 700,
      color: new THREE.Color(0xff2a38),
      emissive: new THREE.Color(0xff2a38),
      emissiveIntensity: 1.6
    });
    iconMesh.position.set(0, discMesh.position.y, 0.03);
    iconMesh.userData = { originalEmissive: 1.6 };
    cardGroup.add(iconMesh);

    // Title text
    const titleMesh = ctx.fontAtlas(cardData.title, {
      font: 'Lora',
      size: 20,
      weight: 600,
      color: new THREE.Color(0xe8ecf2)
    });
    titleMesh.position.set(
      -cardWidth / 2 + 0.375,
      discMesh.position.y - 0.55,
      0.03
    );
    cardGroup.add(titleMesh);

    // Body text
    const bodyMesh = ctx.fontAtlas(cardData.body, {
      font: 'JetBrains Mono',
      size: 13,
      weight: 400,
      color: new THREE.Color(0xa8afbf),
      maxWidth: cardWidth - 0.75
    });
    bodyMesh.position.set(
      -cardWidth / 2 + 0.375,
      titleMesh.position.y - 0.525,
      0.03
    );
    cardGroup.add(bodyMesh);

    // Interaction handlers
    cardGroup.userData = {
      isHovered: false,
      iconMesh,
      handlers: {
        onHover: () => {
          if (cardGroup.userData.isHovered) return;
          cardGroup.userData.isHovered = true;

          gsap.to(cardGroup.position, {
            y: 0.06,
            z: 0.12,
            duration: 0.18,
            ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
          });

          if (iconMesh.material && typeof iconMesh.material.emissiveIntensity === 'number') {
            gsap.to(iconMesh.material, {
              emissiveIntensity: 2.2,
              duration: 0.18
            });
          }
        },
        onUnhover: () => {
          if (!cardGroup.userData.isHovered) return;
          cardGroup.userData.isHovered = false;

          gsap.to(cardGroup.position, {
            y: 0,
            z: 0,
            duration: 0.18,
            ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
          });

          if (iconMesh.material && typeof iconMesh.material.emissiveIntensity === 'number') {
            gsap.to(iconMesh.material, {
              emissiveIntensity: 1.6,
              duration: 0.18
            });
          }
        }
      }
    };

    group.add(cardGroup);
    cards.push(cardGroup);
  });

  // Stagger-cards animation: fade-up
  const tl = gsap.timeline();

  cards.forEach((card, idx) => {
    card.position.y = 0.2;

    tl.to(card.position, {
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
    }, idx * 0.08);
  });

  timelines.push(tl);

  group.userData = {
    handlers: {},
    cleanup: () => {
      timelines.forEach(t => t.kill());
      gsap.killTweensOf(cards);

      cards.forEach(card => {
        card.traverse(child => {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (child.material.map) child.material.map.dispose();
            child.material.dispose();
          }
        });
      });
    }
  };

  return group;
};

export default createNode;
